import pandas as pd

def parse_dates(df):
    # Check if 'Created Date' column exists and is not None
    if "Created Date" in df.columns and df["Created Date"].notnull().all():
        df["Created Date"] = pd.to_datetime(df["Created Date"], format="%Y-%m-%d")

    # Check if 'Close Date' column exists and is not None
    if "Close Date" in df.columns and df["Close Date"].notnull().all():
        df["Close Date"] = pd.to_datetime(df["Close Date"], format="%Y-%m-%d")

    return df
